const TANK_TYPES = {"1":["Conventional tank","Réservoir classique"],"2":["Induced draft","Tirage induit"],"4":["Instantaneous","Instantané"],"8":["Heat pump","Thermopompe"],"11":["Condensing","Condensation"]};
