const collapsedEnvelopeSections=new Set();
let selectedEnvelopeWallId=null;
let envelopeSectionFilter="all";
const selectedOpeningIds=new Set();
const ENVELOPE_SECTION_FILTERS=[
  {id:"all", label:"All"},
  {id:"foundation", label:"Foundation"},
  {id:"walls", label:"Walls"},
  {id:"windows", label:"Windows"},
  {id:"doors", label:"Doors"},
  {id:"floors", label:"Exposed Floors"},
  {id:"ceilings", label:"Ceilings"}
];
const COMPONENT_TYPE_SECTION={
  Basement:"foundation",
  Wall:"walls",
  Window:"windows",
  Door:"doors",
  FloorHeader:"walls",
  Ceiling:"ceilings",
  Floor:"floors"
};
function focusEnvelopeSection(id){
  const next=(!id || id==="all")?"all":id;
  if(envelopeSectionFilter!==next) selectedOpeningIds.clear();
  envelopeSectionFilter=next;
  if(next!=="all") collapsedEnvelopeSections.delete(next);
}
function focusEnvelopeSectionForType(type){
  const id=COMPONENT_TYPE_SECTION[type];
  if(id) focusEnvelopeSection(id);
}
function envelopeJumpHTML(sectionCounts){
  return `<nav class="envelope-jump" aria-label="Filter envelope sections">
    ${ENVELOPE_SECTION_FILTERS.map(({id,label})=>{
      const active=envelopeSectionFilter===id;
      const count=id==="all"?"":` <span class="envelope-jump-count">${sectionCounts[id]||0}</span>`;
      return `<button type="button" class="envelope-jump-link${active?" is-active":""}" data-envelope-filter="${esc(id)}" aria-pressed="${active?"true":"false"}">${esc(label)}${count}</button>`;
    }).join("")}
  </nav>`;
}
function componentCounts(){return {Basement:xpa("/HouseFile/House/Components/Basement").length,Wall:xpa("/HouseFile/House/Components/Wall").length,Window:xpa("/HouseFile/House/Components//Window").length,Door:xpa("/HouseFile/House/Components//Door").length,FloorHeader:xpa("/HouseFile/House/Components//FloorHeader").length,Ceiling:xpa("/HouseFile/House/Components/Ceiling").length,Floor:xpa("/HouseFile/House/Components/Floor").length};}
function nodeLabel(n){return n?.querySelector(":scope > Label")?.textContent?.trim() || `${n?.tagName||"Component"} ${n?.getAttribute("id")||""}`;}
function childrenOf(n){const c=[...n.children].find(x=>x.tagName==="Components");return c?[...c.children]:[];}
function pluralize(count, singular, plural=singular+"s"){return `${count} ${count===1?singular:plural}`;}
function childCountSummary(kids){
  if(!kids.length) return "";
  const order=["Window","Door","FloorHeader","Wall","Ceiling","Floor","Basement"];
  const counts={};
  kids.forEach(k=>{counts[k.tagName]=(counts[k.tagName]||0)+1;});
  const labels={Window:["window","windows"],Door:["door","doors"],FloorHeader:["header","headers"],Wall:["wall","walls"],Ceiling:["ceiling","ceilings"],Floor:["floor","floors"],Basement:["basement","basements"]};
  const parts=[];
  order.forEach(tag=>{
    const n=counts[tag]; if(!n) return;
    const [one,many]=labels[tag]||[tag.toLowerCase(),tag.toLowerCase()+"s"];
    parts.push(pluralize(n, one, many));
    delete counts[tag];
  });
  Object.entries(counts).forEach(([tag,n])=>parts.push(pluralize(n, tag.toLowerCase())));
  return parts.join(" · ");
}
function componentMetrics(n){
  const tag=n.tagName, u=m=>unitLabel(m);
  if(tag==="Wall"){
    const m=n.querySelector(":scope > Measurements");
    return [
      {label:"Height", value:`${fromSI(m?.getAttribute("height"),"length")} ${u("length")}`},
      {label:"Perimeter", value:`${fromSI(m?.getAttribute("perimeter"),"length")} ${u("length")}`}
    ];
  }
  if(tag==="Window"){
    const m=n.querySelector(":scope > Measurements");
    return [{label:"Size", value:`${fromSI(m?.getAttribute("width"),"mm")} × ${fromSI(m?.getAttribute("height"),"mm")} ${u("mm")}`}];
  }
  if(tag==="Door"){
    const m=n.querySelector(":scope > Measurements");
    return [{label:"Size", value:`${fromSI(m?.getAttribute("width"),"door")} × ${fromSI(m?.getAttribute("height"),"door")} ${u("door")}`}];
  }
  if(tag==="Ceiling"||tag==="Floor"){
    const m=n.querySelector(":scope > Measurements");
    const metrics=[{label:"Area", value:`${fromSI(m?.getAttribute("area"),"area")} ${u("area")}`}];
    if(m?.getAttribute("length")) metrics.push({label:"Length", value:`${fromSI(m.getAttribute("length"),"length")} ${u("length")}`});
    return metrics;
  }
  if(tag==="Basement"){
    const fm=n.querySelector(":scope > Floor > Measurements");
    const wm=n.querySelector(":scope > Wall > Measurements");
    return [
      {label:"Area", value:`${fromSI(fm?.getAttribute("area"),"area")} ${u("area")}`},
      {label:"Height", value:`${fromSI(wm?.getAttribute("height"),"length")} ${u("length")}`},
      {label:"Depth", value:`${fromSI(wm?.getAttribute("depth"),"length")} ${u("length")}`}
    ];
  }
  if(tag==="FloorHeader"){
    const m=n.querySelector(":scope > Measurements");
    return [
      {label:"Height", value:`${fromSI(m?.getAttribute("height"),"length")} ${u("length")}`},
      {label:"Perimeter", value:`${fromSI(m?.getAttribute("perimeter"),"length")} ${u("length")}`}
    ];
  }
  return [];
}
function componentMeta(n){return componentMetrics(n).map(m=>`${m.label} ${m.value}`).join(" · ");}
function constructionLabel(n){
  if(n.tagName==="Window"){
    const idref=av(q(n,"Construction > Type"),"idref");
    if(idref){
      const code=xp(`/HouseFile/Codes/Window//Code[@id='${idref}']`);
      const label=code?.querySelector("Label")?.textContent?.trim();
      if(label) return label;
    }
    return q(n,"Construction > Type")?.textContent?.trim() || idref || "No construction";
  }
  if(n.tagName==="Door"){
    const type=q(n,"Construction > Type");
    const code=av(type,"code");
    return type?.querySelector(":scope > English")?.textContent?.trim()
      || DOOR_TYPES[code]?.[0]
      || (code?`Door type ${code}`:"No construction");
  }
  if(n.tagName==="Ceiling"){
    const idref=av(q(n,"Construction > CeilingType"),"idref");
    if(idref){
      const code=xp(`/HouseFile/Codes/Ceiling//Code[@id='${idref}']`);
      const label=code?.querySelector("Label")?.textContent?.trim();
      if(label) return label;
    }
    return q(n,"Construction > CeilingType")?.textContent?.trim() || idref || "No construction";
  }
  return "";
}
function constructionOptionsForKind(kind){
  if(kind==="Window") return codeList("Window");
  if(kind==="Door") return doorTypeOptions();
  if(kind==="Ceiling") return codeList("Ceiling");
  return [];
}
function openingConstructionSelectHTML(n, compact=false){
  const id=n.getAttribute("id");
  const kind=n.tagName;
  const items=constructionOptionsForKind(kind);
  if(!items.length) return "";
  let cur="";
  if(kind==="Window") cur=av(q(n,"Construction > Type"),"idref");
  else if(kind==="Door") cur=av(q(n,"Construction > Type"),"code","6");
  else if(kind==="Ceiling") cur=av(q(n,"Construction > CeilingType"),"idref");
  const label=compact
    ? `<span class="sr-only">Construction</span>`
    : `<span>Construction</span>`;
  return `<label class="inline-construction${compact?" is-compact":""}">${label}<select data-opening-construction="${esc(id)}" data-opening-kind="${esc(kind)}" aria-label="Construction for ${esc(nodeLabel(n))}">${optionHTML(items,cur)}</select></label>`;
}
function componentChildHTML(k,depth=0){
  const nested=childrenOf(k);
  const cons=(k.tagName==="Window"||k.tagName==="Door")?openingConstructionSelectHTML(k,true):"";
  const consText=constructionLabel(k);
  return `<div class="child-row" style="margin-left:${Math.min(depth,4)*18}px"><span class="badge">${k.tagName}</span><strong>${esc(nodeLabel(k))}</strong><span class="child-meta">${esc(componentMeta(k))}${consText?` · ${esc(consText)}`:""}</span>${cons}<span class="child-actions"><button class="mini" data-edit-id="${esc(k.getAttribute("id"))}">Edit</button> <button class="mini danger" data-delete-id="${esc(k.getAttribute("id"))}">Delete</button></span></div>${nested.map(x=>componentChildHTML(x,depth+1)).join("")}`;
}
function componentCardHTML(n){
  const id=n.getAttribute("id"), kids=childrenOf(n);
  const metrics=componentMetrics(n);
  const childSummary=childCountSummary(kids);
  const showOpeningsSlot=n.tagName==="Wall"||n.tagName==="Basement"||kids.length>0;
  const metricHTML=metrics.length
    ? `<div class="metric-row" aria-label="Key measurements">${metrics.map(m=>`<span class="metric"><span class="metric-label">${esc(m.label)}</span> ${esc(m.value)}</span>`).join("")}</div>`
    : "";
  let openingsHTML="";
  if(showOpeningsSlot){
    if(kids.length){
      const childrenOpen=kids.length<=3?" open":"";
      openingsHTML=`<details class="component-children"${childrenOpen}><summary>Openings</summary><div class="children">${kids.map(k=>componentChildHTML(k,0)).join("")}</div></details>`;
    }else{
      openingsHTML=`<p class="child-count muted">No windows or doors</p>`;
    }
  }
  return `<article class="component-card" data-component-id="${esc(id)}">
    <div class="component-head">
      <div class="component-title">
        <span class="badge">${n.tagName}</span>
        <div>
          <h3>${esc(nodeLabel(n))}</h3>
          ${metricHTML}
          <p class="child-count${kids.length?"":" muted"}">${kids.length?esc(childSummary):"No openings"}</p>
        </div>
      </div>
      <div class="component-actions">
        <button type="button" class="mini" data-edit-id="${esc(id)}">Edit</button>
        <button type="button" class="mini danger" data-delete-id="${esc(id)}">Delete</button>
      </div>
    </div>
    ${kids.length?openingsHTML:""}
  </article>`;
}
function sectionCountLabel(id, count){
  const map={
    foundation:["basement","basements"],
    walls:["wall","walls"],
    windows:["window","windows"],
    doors:["door","doors"],
    ceilings:["ceiling","ceilings"],
    floors:["exposed floor","exposed floors"]
  };
  const [one,many]=map[id]||["item","items"];
  return pluralize(count, one, many);
}
function componentParent(n){
  const comps=n?.parentElement;
  if(comps?.tagName==="Components") return comps.parentElement;
  return null;
}
function openingRowSecondary(n){
  if(n.tagName==="Window"||n.tagName==="Door"){
    const parent=componentParent(n);
    return parent?`${parent.tagName}: ${nodeLabel(parent)}`:"No parent";
  }
  if(n.tagName==="Ceiling"){
    const m=direct(n,"Measurements");
    const s=q(n,"Measurements > Slope");
    const parts=[];
    if(m?.getAttribute("heelHeight")!=null) parts.push(`Heel ${fromSI(m.getAttribute("heelHeight"),"length")} ${unitLabel("length")}`);
    if(s?.getAttribute("value")) parts.push(`Slope ${s.getAttribute("value")}`);
    return parts.join(" · ") || "Ceiling assembly";
  }
  return "—";
}
function openingRowHTML(n){
  const id=n.getAttribute("id");
  const metrics=componentMetrics(n).map(m=>m.value).join(" · ");
  const secondary=openingRowSecondary(n);
  const checked=selectedOpeningIds.has(id);
  return `<div class="opening-row${checked?" is-selected":""}" data-component-id="${esc(id)}" role="row">
    <label class="opening-pick check"><input type="checkbox" data-opening-pick="${esc(id)}"${checked?" checked":""}><span class="sr-only">Select ${esc(nodeLabel(n))}</span></label>
    <div class="opening-row-main">
      <strong class="opening-row-label">${esc(nodeLabel(n))}</strong>
      <span class="opening-row-meta">${esc(metrics||"—")}</span>
    </div>
    <span class="opening-row-parent" title="${esc(secondary)}">${esc(secondary)}</span>
    ${openingConstructionSelectHTML(n,true)}
    <span class="opening-row-actions component-actions">
      <button type="button" class="mini" data-edit-id="${esc(id)}">Edit</button>
      <button type="button" class="mini danger" data-delete-id="${esc(id)}">Delete</button>
    </span>
  </div>`;
}
function openingsSectionBodyHTML(kind, nodes, empty){
  if(!nodes.length) return `<div class="envelope-empty">${esc(empty)}</div>`;
  const idSet=new Set(nodes.map(n=>n.getAttribute("id")));
  [...selectedOpeningIds].forEach(id=>{ if(!idSet.has(id)) selectedOpeningIds.delete(id); });
  const selectedCount=nodes.filter(n=>selectedOpeningIds.has(n.getAttribute("id"))).length;
  const bulkItems=[{id:"",label:"Choose construction…"}].concat(constructionOptionsForKind(kind));
  const allSelected=selectedCount===nodes.length && nodes.length>0;
  const listLabel=kind==="Window"?"Windows":kind==="Door"?"Doors":kind==="Ceiling"?"Ceilings":kind;
  const secondaryHead=(kind==="Window"||kind==="Door")?"Parent":"Details";
  return `<div class="opening-bulk-bar">
      <label class="check"><input type="checkbox" data-opening-select-all${allSelected?" checked":""}> Select all (${nodes.length})</label>
      <span class="opening-selected-count">${selectedCount} selected</span>
      <label class="inline-construction bulk"><span>Set construction</span><select data-bulk-construction-kind="${esc(kind)}">${optionHTML(bulkItems,"")}</select></label>
      <button type="button" class="button" data-bulk-apply-construction${selectedCount?"":" disabled"}>Apply to selected</button>
      <button type="button" class="button secondary" data-bulk-apply-all>Apply to all</button>
    </div>
    <div class="opening-row-list" role="table" aria-label="${esc(listLabel)}">
      <div class="opening-row opening-row-head" role="row">
        <span class="opening-pick-spacer" aria-hidden="true"></span>
        <span>Label / size</span>
        <span>${esc(secondaryHead)}</span>
        <span>Construction</span>
        <span class="opening-row-actions-head">Actions</span>
      </div>
      ${nodes.map(openingRowHTML).join("")}
    </div>`;
}
function envelopeSectionHTML({id,title,lead,adds,nodes,empty,bodyHTML,filterOnly=false}){
  if(filterOnly){
    if(envelopeSectionFilter!==id) return "";
  }else if(envelopeSectionFilter!=="all" && envelopeSectionFilter!==id){
    return "";
  }
  const count=nodes.length;
  const collapsed=!filterOnly && envelopeSectionFilter==="all" && collapsedEnvelopeSections.has(id);
  const countLabel=sectionCountLabel(id, count);
  const cards=bodyHTML!=null?bodyHTML:(nodes.map(componentCardHTML).join("")||`<div class="envelope-empty">${esc(empty)}</div>`);
  return `<section class="envelope-group${collapsed?" is-collapsed":""}" data-envelope-section="${esc(id)}" id="envelope-section-${esc(id)}">
    <div class="envelope-group-head">
      <button type="button" class="envelope-toggle" data-toggle-section="${esc(id)}" aria-expanded="${collapsed?"false":"true"}">
        <span class="envelope-chevron" aria-hidden="true">${collapsed?"▸":"▾"}</span>
        <span class="envelope-toggle-text">
          <span class="envelope-title-row"><strong>${esc(title)}</strong> <span class="envelope-count">${esc(countLabel)}</span></span>
          <span class="envelope-lead">${esc(lead)}</span>
        </span>
      </button>
      <div class="add-menu">${adds.map(([type,label])=>`<button type="button" class="button secondary" data-add="${esc(type)}">${esc(label)}</button>`).join("")}</div>
    </div>
    <div class="envelope-group-body"${collapsed?` hidden`:""}>
      ${cards}
    </div>
  </section>`;
}
function wallsSectionBodyHTML(walls, empty){
  if(!walls.length) return `<div class="envelope-empty">${esc(empty)}</div>`;
  if(walls.length<3) return walls.map(componentCardHTML).join("");
  const ids=walls.map(w=>w.getAttribute("id"));
  if(!selectedEnvelopeWallId || !ids.includes(selectedEnvelopeWallId)) selectedEnvelopeWallId=ids[0];
  const selected=walls.find(w=>w.getAttribute("id")===selectedEnvelopeWallId)||walls[0];
  const list=walls.map(w=>{
    const id=w.getAttribute("id");
    const active=id===selected.getAttribute("id");
    const kids=childrenOf(w);
    const metrics=componentMetrics(w).slice(0,2).map(m=>m.value).join(" · ");
    return `<button type="button" class="wall-list-item${active?" is-active":""}" data-select-wall="${esc(id)}" role="option" aria-selected="${active?"true":"false"}">
      <strong>${esc(nodeLabel(w))}</strong>
      <span class="wall-list-meta">${esc(metrics)}</span>
      <span class="wall-list-kids">${esc(childCountSummary(kids)||"No openings")}</span>
    </button>`;
  }).join("");
  return `<div class="walls-master-detail">
    <div class="walls-list" role="listbox" aria-label="Above-grade walls">${list}</div>
    <div class="walls-detail">${componentCardHTML(selected)}</div>
  </div>`;
}
function bindEnvelopeInteractions(root){
  root.querySelectorAll("[data-add]").forEach(b=>b.addEventListener("click",()=>addComponent(b.dataset.add)));
  root.querySelectorAll("[data-edit-id]").forEach(b=>b.addEventListener("click",()=>editById(b.dataset.editId)));
  root.querySelectorAll("[data-delete-id]").forEach(b=>b.addEventListener("click",()=>deleteById(b.dataset.deleteId)));
  root.querySelectorAll("[data-toggle-section]").forEach(b=>b.addEventListener("click",()=>{
    const id=b.dataset.toggleSection;
    if(envelopeSectionFilter!=="all") return; // filtered view always shows the section body
    if(collapsedEnvelopeSections.has(id)) collapsedEnvelopeSections.delete(id);
    else collapsedEnvelopeSections.add(id);
    renderComponents();
  }));
  root.querySelectorAll("[data-select-wall]").forEach(b=>b.addEventListener("click",()=>{
    selectedEnvelopeWallId=b.dataset.selectWall;
    renderComponents();
  }));
  root.querySelectorAll("[data-envelope-filter]").forEach(b=>b.addEventListener("click",()=>{
    focusEnvelopeSection(b.dataset.envelopeFilter);
    renderComponents();
    const target=$("#envelope-section-"+envelopeSectionFilter) || $(".envelope-jump");
    target?.scrollIntoView({behavior:"smooth", block:"start"});
  }));
  root.querySelectorAll("[data-opening-pick]").forEach(cb=>cb.addEventListener("change",()=>{
    const id=cb.dataset.openingPick;
    if(cb.checked) selectedOpeningIds.add(id);
    else selectedOpeningIds.delete(id);
    renderComponents();
  }));
  root.querySelectorAll("[data-opening-select-all]").forEach(cb=>cb.addEventListener("change",()=>{
    const cards=[...root.querySelectorAll("[data-opening-pick]")];
    cards.forEach(box=>{
      if(cb.checked) selectedOpeningIds.add(box.dataset.openingPick);
      else selectedOpeningIds.delete(box.dataset.openingPick);
    });
    renderComponents();
  }));
  root.querySelectorAll("[data-opening-construction]").forEach(sel=>sel.addEventListener("change",()=>{
    applyOpeningConstruction(sel.dataset.openingConstruction, sel.dataset.openingKind, sel.value);
    saveSession();
    toast("Construction updated");
    renderComponents();
  }));
  const bulkSelect=root.querySelector("[data-bulk-construction-kind]");
  const applyBulk=(ids)=>{
    if(!bulkSelect) return;
    const code=bulkSelect.value;
    if(!code){ toast("Choose a construction first"); return; }
    const kind=bulkSelect.dataset.bulkConstructionKind;
    ids.forEach(id=>applyOpeningConstruction(id, kind, code));
    saveSession();
    toast(`Construction applied to ${ids.length} ${kind==="Window"?"window":kind==="Door"?"door":kind==="Ceiling"?"ceiling":"item"}${ids.length===1?"":"s"}`);
    renderComponents();
  };
  root.querySelectorAll("[data-bulk-apply-construction]").forEach(b=>b.addEventListener("click",()=>{
    const ids=[...root.querySelectorAll("[data-opening-pick]:checked")].map(x=>x.dataset.openingPick);
    if(!ids.length){ toast("Select one or more items first"); return; }
    applyBulk(ids);
  }));
  root.querySelectorAll("[data-bulk-apply-all]").forEach(b=>b.addEventListener("click",()=>{
    const ids=[...root.querySelectorAll("[data-opening-pick]")].map(x=>x.dataset.openingPick);
    if(!ids.length) return;
    applyBulk(ids);
  }));
}
function applyOpeningConstruction(id, kind, code){
  const n=findById(id); if(!n) return;
  if(kind==="Window" || n.tagName==="Window") applyWindowCode(n, code);
  else if(kind==="Door" || n.tagName==="Door") applyDoorType(n, code);
  else if(kind==="Ceiling" || n.tagName==="Ceiling") applyCeilingCode(n, code);
}
